class TestLogEntryInvariants:
    """Validate the frozen dataclass constraints for LogEntry."""

    @given(
        term=st.integers(min_value=0, max_value=10**6),
        index=st.integers(min_value=0, max_value=10**6),
        payload=st.binary(max_size=256),
    )
    def test_valid_entries_accepted(self, term: int, index: int, payload: bytes) -> None:
        """Valid entries (non-negative term/index) must be constructed."""
        entry = LogEntry(term=term, index=index, payload=payload)
        assert entry.term == term
        assert entry.index == index
        assert entry.payload == payload

    @given(
        term=st.integers(max_value=-1),
        index=st.integers(min_value=0, max_value=10**6),
        payload=st.binary(max_size=256),
    )
    def test_negative_term_rejected(self, term: int, index: int, payload: bytes) -> None:
        """Negative terms violate Raft invariants and must raise ValueError."""
        with pytest.raises(ValueError, match="term must be non-negative"):
            LogEntry(term=term, index=index, payload=payload)

    @given(
        term=st.integers(min_value=0, max_value=10**6),
        index=st.integers(max_value=-1),
        payload=st.binary(max_size=256),
    )
    def test_negative_index_rejected(self, term: int, index: int, payload: bytes) -> None:
        """Negative indices violate log ordering and must raise ValueError."""
        with pytest.raises(ValueError, match="index must be non-negative"):
            LogEntry(term=term, index=index, payload=payload)

    @given(
        term=st.integers(min_value=0, max_value=10**6),
        index=st.integers(min_value=0, max_value=10**6),
        payload=st.binary(max_size=256),
    )
    def test_immutability(self, term: int, index: int, payload: bytes) -> None:
        """Frozen dataclass must reject attribute mutation."""
        entry = LogEntry(term=term, index=index, payload=payload)
        with pytest.raises(AttributeError):
            entry.term = term + 1  # type: ignore[misc]
        with pytest.raises(AttributeError):
            entry.index = index + 1  # type: ignore[misc]
        with pytest.raises(AttributeError):
            entry.payload = b"mutated"  # type: ignore[misc]

    @given(
        term=st.integers(min_value=0, max_value=10**6),
        index=st.integers(min_value=0, max_value=10**6),
        payload=st.binary(max_size=256),
    )
    def test_equality_and_hashing(self, term: int, index: int, payload: bytes) -> None:
        """Equal entries must hash equally; distinct entries must not collide."""
        entry1 = LogEntry(term=term, index=index, payload=payload)
        entry2 = LogEntry(term=term, index=index, payload=payload)
        assert entry1 == entry2
        assert hash(entry1) == hash(entry2)

        entry3 = LogEntry(term=term + 1, index=index, payload=payload)
        assert entry1 != entry3

    @given(
        term=st.integers(min_value=0, max_value=10**6),
        index=st.integers(min_value=0, max_value=10**6),
        payload=st.binary(max_size=256),
    )
    def test_serialization_roundtrip(self, term: int, index: int, payload: bytes) -> None:
        """Pickle serialization must preserve all fields."""
        entry = LogEntry(term=term, index=index, payload=payload)
        restored = pickle.loads(pickle.dumps(entry))
        assert restored == entry
        assert restored.term == term
        assert restored.index == index
        assert restored.payload == payload

    @given(
        term=st.integers(min_value=0, max_value=10**6),
        index=st.integers(min_value=0, max_value=10**6),
        payload=st.binary(max_size=256),
    )
    def test_deepcopy_independence(self, term: int, index: int, payload: bytes) -> None:
        """Deepcopy must produce an independent object."""
        entry = LogEntry(term=term, index=index, payload=payload)
        copied = deepcopy(entry)
        assert copied == entry
        assert copied is not entry


