class TestNodeRoleEnum:
    """Validate the NodeRole enumeration members and metadata."""

    def test_expected_members_present(self) -> None:
        """Raft defines exactly three roles."""
        expected = {"FOLLOWER", "CANDIDATE", "LEADER"}
        actual = {role.name for role in NodeRole}
        assert actual == expected

    def test_role_values_are_strings(self) -> None:
        """Each role must have a string value for serialization."""
        for role in NodeRole:
            assert isinstance(role.value, str)
            assert len(role.value) > 0

    def test_role_values_unique(self) -> None:
        """Enum values must be unique to prevent aliasing."""
        values = [role.value for role in NodeRole]
        assert len(values) == len(set(values))

    @given(st.sampled_from(list(NodeRole)))
    def test_role_from_value_roundtrip(self, role: NodeRole) -> None:
        """Constructing from value must recover the original enum member."""
        assert NodeRole(role.value) == role

    @given(st.text())
    def test_invalid_role_value_rejected(self, value: str) -> None:
        """Unknown string values must raise ValueError."""
        assume(value not in {role.value for role in NodeRole})
        with pytest.raises(ValueError):
            NodeRole(value)

    def test_role_ordering(self) -> None:
        """FOLLOWER < CANDIDATE < LEADER for deterministic comparisons."""
        assert NodeRole.FOLLOWER < NodeRole.CANDIDATE < NodeRole.LEADER


