class TestConsensusStateMachine:
    """Validate legal and illegal state transitions in the consensus state machine."""

    @given(
        current_role=st.sampled_from(list(NodeRole)),
        current_term=st.integers(min_value=0, max_value=10**6),
        new_term=st.integers(min_value=0, max_value=10**6),
    )
    def test_term_monotonicity(self, current_role: NodeRole, current_term: int, new_term: int) -> None:
        """Terms must never decrease; transitions to lower terms are illegal."""
        machine = ConsensusStateMachine(role=current_role, term=current_term)
        assume(new_term < current_term)
        with pytest.raises(ValueError, match="term cannot decrease"):
            machine.update_term(new_term)

    @given(
        current_role=st.sampled_from(list(NodeRole)),
        current_term=st.integers(min_value=0, max_value=10**6),
        new_term=st.integers(min_value=0, max_value=10**6),
    )
    def test_term_increase_allowed(self, current_role: NodeRole, current_term: int, new_term: int) -> None:
        """Terms may increase; role must revert to FOLLOWER on term bump."""
        machine = ConsensusStateMachine(role=current_role, term=current_term)
        assume(new_term > current_term)
        machine.update_term(new_term)
        assert machine.term == new_term
        assert machine.role == NodeRole.FOLLOWER

    @given(
        current_role=st.sampled_from(list(NodeRole)),
        current_term=st.integers(min_value=0, max_value=10**6),
    )
    def test_follower_to_candidate(self, current_role: NodeRole, current_term: int) -> None:
        """Only FOLLOWER may become CANDIDATE (election timeout)."""
        machine = ConsensusStateMachine(role=current_role, term=current_term)
        assume(current_role == NodeRole.FOLLOWER)
        machine.start_election()
        assert machine.role == NodeRole.CANDIDATE

    @given(
        current_role=st.sampled_from(list(NodeRole)),
        current_term=st.integers(min_value=0, max_value=10**6),
    )
    def test_non_follower_cannot_start_election(self, current_role: NodeRole, current_term: int) -> None:
        """CANDIDATE and LEADER must not start elections."""
        machine = ConsensusStateMachine(role=current_role, term=current_term)
        assume(current_role != NodeRole.FOLLOWER)
        with pytest.raises(ValueError, match="only followers can start elections"):
            machine.start_election()

    @given(
        current_role=st.sampled_from(list(NodeRole)),
        current_term=st.integers(min_value=0, max_value=10**6),
    )
    def test_candidate_to_leader(self, current_role: NodeRole, current_term: int) -> None:
        """Only CANDIDATE may become LEADER (majority vote)."""
        machine = ConsensusStateMachine(role=current_role, term=current_term)
        assume(current_role == NodeRole.CANDIDATE)
        machine.win_election()
        assert machine.role == NodeRole.LEADER

    @given(
        current_role=st.sampled_from(list(NodeRole)),
        current_term=st.integers(min_value=0, max_value=10**6),
    )
    def test_non_candidate_cannot_become_leader(self, current_role: NodeRole, current_term: int) -> None:
        """FOLLOWER and LEADER must not win elections."""
        machine = ConsensusStateMachine(role=current_role, term=current_term)
        assume(current_role != NodeRole.CANDIDATE)
        with pytest.raises(ValueError, match="only candidates can win elections"):
            machine.win_election()


