class TestPrimitiveStrategies:
    """Validate that exposed Hypothesis strategies produce valid data."""

    @given(st.data())
    @settings(suppress_health_check=[HealthCheck.too_slow], max_examples=100)
    def test_log_entry_strategy(self, data: st.DataObject) -> None:
        """The log_entry strategy must always produce valid LogEntry objects."""
        entry = data.draw(primitives.log_entry_strategy())
        assert isinstance(entry, LogEntry)
        assert entry.term >= 0
        assert entry.index >= 0

    @given(st.data())
    @settings(suppress_health_check=[HealthCheck.too_slow], max_examples=100)
    def test_node_state_strategy(self, data: st.DataObject) -> None:
        """The node_state strategy must always produce valid NodeState objects."""
        state = data.draw(primitives.node_state_strategy())
        assert isinstance(state, NodeState)
        assert state.term >= 0
        assert state.role in NodeRole
        # Log entries must be sorted by index
        indices = [entry.index for entry in state.log]
        assert indices == sorted(indices)

    @given(st.data())
    @settings(suppress_health_check=[HealthCheck.too_slow], max_examples=100)
    def test_log_strategy_sorted(self, data: st.DataObject) -> None:
        """The log strategy must produce entries with strictly increasing indices."""
        log = data.draw(primitives.log_strategy())
        indices = [entry.index for entry in log]
        assert indices == sorted(indices)
        # No duplicate indices in a valid log
        assert len(indices) == len(set(indices))


