class TestEdgeCases:
    """Targeted edge-case validation for boundary conditions."""

    def test_empty_log_state(self) -> None:
        """A NodeState with an empty log must be valid."""
        state = NodeState(
            node_id="test-node",
            role=NodeRole.FOLLOWER,
            term=0,
            log=[],
        )
        assert state.log == []

    def test_zero_term_entry(self) -> None:
        """Term 0 is valid (initial term in Raft)."""
        entry = LogEntry(term=0, index=0, payload=b"")
        assert entry.term == 0

    def test_large_payload(self) -> None:
        """Large payloads must be accepted without truncation."""
        payload = b"x" * (1024 * 1024)  # 1 MB
        entry = LogEntry(term=1, index=1, payload=payload)
        assert len(entry.payload) == len(payload)

    def test_unicode_payload(self) -> None:
        """Unicode payloads must be preserved exactly."""
        payload = "héllo wörld".encode("utf-8")
        entry = LogEntry(term=1, index=1, payload=payload)
        assert entry.payload.decode("utf-8") == "héllo wörld"

    def test_maximum_index(self) -> None:
        """The maximum allowed index must be accepted."""
        entry = LogEntry(term=1, index=10**6, payload=b"")
        assert entry.index == 10**6

    def test_maximum_term(self) -> None:
        """The maximum allowed term must be accepted."""
        entry = LogEntry(term=10**6, index=1, payload=b"")
        assert entry.term == 10**6


