# 7. PERFORMANCE SANITY TESTS
# -----------------------------------------------------------------------------

class TestPerformanceSanity:
    """Coarse performance validation to catch pathological regressions."""

    @pytest.mark.parametrize("log_size", [10, 100, 1000])
    def test_large_log_construction(self, log_size: int) -> None:
        """Constructing NodeState with large logs must complete quickly."""
        import time

        log = [
            LogEntry(term=i // 10, index=i, payload=b"x" * 100)
            for i in range(log_size)
        ]
        start = time.perf_counter()
        state = NodeState(
            node_id="perf-node",
            role=NodeRole.LEADER,
            term=log_size,
            log=log,
        )
        elapsed = time.perf_counter() - start
        assert state is not None
        assert elapsed < 1.0  # 1 second upper bound for construction

    def test_state_machine_transition_performance(self) -> None:
        """State machine transitions must be O(1) and fast."""
        import time

        machine = ConsensusStateMachine(role=NodeRole.FOLLOWER, term=0)
        start = time.perf_counter()
        for _ in range(10000):
            machine.start_election()
            machine.win_election()
            machine.update_term(machine.term + 1)
        elapsed = time.perf_counter() - start
        assert elapsed < 1.0  # 10k transitions in under 1 second


